update public.fields set verification_status='verified_against_standard', verification_quote='An intensive basic instruction must be carried out according to the following factors: overview of the parameters to be analysed, introduction to parameter-specific sampling including the required pre-treatment of samples and preservation, practice of the operating method for each parameter with representative wastewater samples of the planned cases of application (autonomous completion and handling) according to the given work instruction, — printed p.11', verification_note='md-verified 2026-09-09 (§4.3.1 Basic Instruction, printed p.11) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.7; attestation checkbox for gate CR-011; gate is homed on worksheet -03 (Anwendung & Methodenauswahl) although worksheet -04 is "Einweisung & Ueberwachung des Personals" and holds basic_instruction_done (mis-home, STAGED)', verified_at=now() where id='16428ffc-6617-4d6f-9a87-f1686641106c' and verification_status not in ('verified_against_standard','corrected');
