update public.fields set verification_status='verified_against_standard', verification_quote='IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE — printed p.35', verification_note='md-verified 2026-09-09 (IQC-Card 5 Sheet 1, printed p.35) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.20', verified_at=now() where id='69b9b33b-e1cd-44b7-b5f9-a375cb1c27e2' and verification_status not in ('verified_against_standard','corrected');
