update public.fields set verification_status='verified_against_standard', verification_quote='IQC-Card 5, Sheet 3 - standard addition (general procedure): 2. Single steps: Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3), Standard addition by adding the VOLUME STANDARD (column 5) in familiar CONCENTRATION STANDARD (column 6) to the defined VOLUME SAMPLE (column 4), Determination of MEASURED VALUE SPIKED SAMPLE (column 9). | 3. Calculation: NOMINAL VALUE SPIKED SAMPLE (NSS, column 8): NSS = [(volume sample · measured value original sample) + (volume standard · concentration standard)] / (volume sample + volume standard) — printed p.36', verification_note='md-verified 2026-09-09 (IQC-Card 5 Sheet 3, printed p.36) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.21', verified_at=now() where id='29f4a45c-b549-4491-885e-5cac4794fd87' and verification_status not in ('verified_against_standard','corrected');
