update public.fields set verification_status='verified_against_standard', verification_quote='Overview of instruction and training: This overview serves as a proof of training according to Section 4.3.3 of the Standard. Here the completed basic introduction as well as all internal and external successive training are recorded. Here, for example, also supportive visits by the manufacturer and DWA-courses must be registered. | Sheet 2 - Overview of Instructions and Training: 1 Event: topic and organising party | 2 Date | 3 Signature supervisor — printed p.62 and 66', verification_note='md-verified 2026-09-09 (IQC-Card 10 Sheet 2, printed p.62 and 66) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.36', verified_at=now() where id='d49bbbd8-ca37-4753-adf9-a7df807f57a3' and verification_status not in ('verified_against_standard','corrected');
-- deviation_feature  [ATV-A-704E-12]
update public.fields set verification_status='verified_against_standard', verification_quote='Here, the date of the deviation is put down in column 1. The name of the person who detects the deviation (column 2), the type of distinctive features (column 3) and in which IQC-Card they are documented (column 4) are also noted. As soon as the cause is known, it is documented in column 5 with the measured taken (column 6). The result of the measures introduced is entered together with date (date 7), the result of the measures (column 8) and the name of the person who determined the result (column 9). — printed p.67', verification_note='md-verified 2026-09-09 (IQC-Card 11, printed p.67) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.36; FINDING: the field description cites "IGC-Card 11 column 2"; the printed text puts the type of distinctive features in COLUMN 3 (column 2 is the name of the person). Wrong column reference (STAGED)', verified_at=now() where id='e9cae4bd-0835-45ea-8447-5248e86f1d49' and verification_status not in ('verified_against_standard','corrected');
