-- ---- Section B: equations (6 rows) ----

-- EQ-01  mean_value = mean_value = SUM(single_result_i) / n_determinations
update public.equations set verification_status='verified_against_standard', verification_quote='From the single results a mean value must be produced, which represents the measuring result. Here, all single results must be included in the mean. | From the single measured values the mean (add single measured values and divide them by the number of the measured values; column 7) is produced. | IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.29 and 30', verification_note='md-verified 2026-09-09 (IQC-Card 3, printed p.29 and 30) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.18; formula mean = sum(single values)/n matches the printed column-7 rule exactly', verified_at=now() where id='c4f4944e-9329-4a62-9724-3e9637a0891c' and verification_status <> 'verified_against_standard';
-- EQ-02  deviation_single_pct = deviation_single_pct = 100 * (single_result_i - mean_value) / mean_value
update public.equations set verification_status='verified_against_standard', verification_quote='The greatest difference in the single measured values is entered into the IQC-Card in mg/l (column 8) and in % (greatest difference of the single measured values divided by the mean value; column 9). In column 10 the result of the control measure is documented. | IQC-Card 3 - Multiple Determinations (form header): 1 Date | 2 Name | 3 Sample designation | 4 Measured value 1 [mg/l] | 5 Measured value 2 [mg/l] | 6 Measured value 3 [mg/l] | 7 Mean [mg/l] | 8 Greatest spread Difference [mg/l] | 9 Greatest spread Col 8 x 100% / Col 7 [%] | 10 Interpretation: Quality target achieved? — printed p.29 and 30', verification_note='md-verified 2026-09-09 (IQC-Card 3, printed p.29 and 30) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.18; FINDING - the FORMULA is NOT confirmed: printed column 9 is "Greatest spread: Col 8 x 100% / Col 7", i.e. the greatest DIFFERENCE of the single values divided by the mean. The encoded formula 100*(single_result_i - mean_value)/mean_value is a different statistic. This row records EVIDENCE of the printed rule only; changing the formula is a STAGED ruling, not done here', verified_at=now() where id='a4287f3a-2d8f-4d0e-8f51-8ce6843496cf' and verification_status <> 'verified_against_standard';
-- EQ-03  calculated_value = calculated_value = (total_volume / sample_volume) * measured_value_diluted_sample
update public.equations set verification_status='verified_against_standard', verification_quote='IQC-Card 5, Sheet 1 - Dilution: 2. Single steps: a) Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3) b) Dilution c) Determination of MEASURED VALUE DILUTED SAMPLE (column 5) | 3. Formulas for calculation: DILUTION FACTOR (column 4) = TOTAL VOLUME / SAMPLE VOLUME. CALCULATED VALUE (column 6) = DILUTION FACTOR · MEASURED VALUE DILUTED SAMPLE — printed p.35', verification_note='md-verified 2026-09-09 (IQC-Card 5 Sheet 1, printed p.35) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.20; formula matches the printed "CALCULATED VALUE (column 6) = DILUTION FACTOR . MEASURED VALUE DILUTED SAMPLE" with DILUTION FACTOR = TOTAL VOLUME / SAMPLE VOLUME', verified_at=now() where id='f203bcc2-f1d4-4a40-85a6-de11bd2e7894' and verification_status <> 'verified_against_standard';
-- EQ-04  NSS = NSS = (volume_sample * measured_value_original_sample + volume_standard * concentration_standard) / (volume_sample + volume_standard)
update public.equations set verification_status='verified_against_standard', verification_quote='IQC-Card 5, Sheet 3 - standard addition (general procedure): 2. Single steps: Determination of the MEASURED VALUE ORIGINAL SAMPLE (column 3), Standard addition by adding the VOLUME STANDARD (column 5) in familiar CONCENTRATION STANDARD (column 6) to the defined VOLUME SAMPLE (column 4), Determination of MEASURED VALUE SPIKED SAMPLE (column 9). | 3. Calculation: NOMINAL VALUE SPIKED SAMPLE (NSS, column 8): NSS = [(volume sample · measured value original sample) + (volume standard · concentration standard)] / (volume sample + volume standard) — printed p.36', verification_note='md-verified 2026-09-09 (IQC-Card 5 Sheet 3, printed p.36) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.21; formula matches the printed NSS fraction exactly', verified_at=now() where id='56f648dc-a38d-4f4a-81da-401d3ba36eb5' and verification_status <> 'verified_against_standard';
-- EQ-05  deviation_equivalency_pct = deviation_equivalency_pct = 100 * (measured_value_operating - nominal_value_reference) / nominal_value_reference
update public.equations set verification_status='verified_against_standard', verification_quote='The following information should be documented in Card 6: [...] mean value of own measurements (column 5), nominal or mean value, which was calculated within the scope of the equivalency measurements (column 6), deviation of the calculated mean value from the nominal or mean value in mg/l (column 7) and in per cent (column 8), result of the own interpretation [...] (column 9). | IQC-Card 6 - Equivalency Measurements (form header): 1 Date | 2 Name | 3 Sample designation | 4 Parameter | 5 Mean [mg/l] | 6 Nominal value or mean of the equivalency measurements [mg/l] | 7 Deviation of the mean from the nominal value [mg/l] | 8 Deviation relative [%] | 9 Interpretation: Quality target achieved? — printed p.43 and 45', verification_note='md-verified 2026-09-09 (IQC-Card 6, printed p.43 and 45) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.25; the printed form gives no algebraic expression for column 8; the formula is confirmed by arithmetic on the printed example (p.45 row 1: mean 18, nominal 19, col 7 = -1, col 8 = -5.3 % = -1 x 100 / 19)', verified_at=now() where id='3da75786-3ecf-4f6b-996a-bdd86e486605' and verification_status <> 'verified_against_standard';
-- EQ-06  deviation_parallel_pct = deviation_parallel_pct = 100 * (measured_value_operating - measured_value_reference) / measured_value_reference
update public.equations set verification_status='verified_against_standard', verification_quote='[...] the measured value (usually mean value) of the operating method (column 8) is put down. The laboratory/authority that carries out the measurements according to the reference method (column 6) is also documented together with the determined measured value (column 7). The difference between both measured values must be formed and must be entered into the IQC-Card in absolute (column 9) as well as percental value (column 10) with reference to the result of the external laboratory. | IQC-Card 7 - Parallel Measurements to the Reference Method (form header): 7 Referenced monitoring Measured value [mg/l] | 8 Measured value of the operating method [mg/l] | 9 Deviation absolute Col8-Col7 [mg/l] | 10 Deviation relative Col9 x 100/Col7 [%] | 11/12 Permissible deviation Condition [mg/l] [%] | 13 Interpretation: Quality target achieved? — printed p.46 and 48', verification_note='md-verified 2026-09-09 (IQC-Card 7, printed p.46 and 48) [VA-OCR]; source is OCR of a scanned PDF with no text layer; image-confirmed on the rendered page PDF p.27; formula matches the printed column-10 rule "Deviation relative Col9 x 100/Col7" with Col9 = Col8 - Col7 = operating - reference', verified_at=now() where id='5bb589a2-3706-4651-8e8c-13ac5cdd6c60' and verification_status <> 'verified_against_standard';

-- end of pack: 91 field rows + 6 equation rows = 97 statements.
